"""Generate buildless web messages and native Android resources from one reviewed catalogue."""
# DOC L0002: Rende disponibili le dipendenze esplicite di questa riga: from pathlib import Path. Il modulo chiamante resta responsabile del loro uso nel flusso descritto sopra.
from pathlib import Path
# DOC L0003: Rende disponibili le dipendenze esplicite di questa riga: import hashlib,json,re. Il modulo chiamante resta responsabile del loro uso nel flusso descritto sopra.
import hashlib,json,re
# DOC L0004: Rende disponibili le dipendenze esplicite di questa riga: from xml.sax.saxutils import escape. Il modulo chiamante resta responsabile del loro uso nel flusso descritto sopra.
from xml.sax.saxutils import escape
# DOC L0005: Esegue il passaggio esplicito «ROOT=Path(__file__).resolve().parent.parent» nel flusso: Generatore del catalogo web e delle risorse Android.
ROOT=Path(__file__).resolve().parent.parent
# DOC L0006: Esegue il passaggio esplicito «messages=json.loads((ROOT/'locales/messages.json').read_text(encoding='utf-8'))» nel flusso: Generatore del catalogo web e delle risorse Android.
messages=json.loads((ROOT/'locales/messages.json').read_text(encoding='utf-8'))
# DOC L0007: Elabora gli elementi o le iterazioni indicati; gli indici distinguono l’ultimo elemento per le pause o i limiti previsti.
for source,values in messages.items():
 # DOC L0008: Verifica la condizione esplicita; un fallimento segnala un contratto non rispettato o rifiuta l’operazione prima di proseguire. Elabora gli elementi o le iterazioni indicati; gli indici distinguono l’ultimo elemento per le pause o i limiti previsti.
 assert len(values) in (2,3) and all(isinstance(v,str) and v for v in values), source
 # DOC L0009: Verifica la condizione esplicita; un fallimento segnala un contratto non rispettato o rifiuta l’operazione prima di proseguire. Elabora gli elementi o le iterazioni indicati; gli indici distinguono l’ultimo elemento per le pause o i limiti previsti.
 for value in values: assert set(re.findall(r'\{\d+\}',source))==set(re.findall(r'\{\d+\}',value)),source
# DOC L0010: Esegue il passaggio esplicito «(ROOT/'web/js/messages.js').write_text('// Generated by scripts/generate-locales.py; edit locales/messages.json.\nexport const messages = '+json.dumps(messages,ensure_ascii=False,s» nel flusso: Generatore del catalogo web e delle risorse Android.
(ROOT/'web/js/messages.js').write_text('// Generated by scripts/generate-locales.py; edit locales/messages.json.\nexport const messages = '+json.dumps(messages,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf-8')
# DOC L0011: Elabora gli elementi o le iterazioni indicati; gli indici distinguono l’ultimo elemento per le pause o i limiti previsti.
ids={source:'msg_'+hashlib.sha256(source.encode()).hexdigest()[:12] for source in messages}
# DOC L0012: Verifica la condizione esplicita; un fallimento segnala un contratto non rispettato o rifiuta l’operazione prima di proseguire.
assert len(set(ids.values()))==len(ids)
# DOC L0013: Elabora gli elementi o le iterazioni indicati; gli indici distinguono l’ultimo elemento per le pause o i limiti previsti.
for locale,index in [('values',None),('values-en',0),('values-es',1)]:
 # DOC L0014: Esegue il passaggio esplicito «folder=ROOT/'android/app/src/main/res'/locale;folder.mkdir(exist_ok=True)» nel flusso: Generatore del catalogo web e delle risorse Android.
 folder=ROOT/'android/app/src/main/res'/locale;folder.mkdir(exist_ok=True)
 # DOC L0015: xml: Passaggio «xml» dello strumento: Generatore del catalogo web e delle risorse Android. Gli argomenti e le operazioni sono descritti nelle righe del corpo.
 def xml(s):return escape(s.replace('\\','\\\\').replace("'","\\'").replace('"','\\"').replace('\n','\\n'))
 # DOC L0016: Associa la risorsa {ids[k]} al testo localizzato «{xml((v[2] if len(v)==3 else k) if index is None else v[index])}», recuperato da AppText attraverso MessageIds.
 (folder/'messages.xml').write_text('<?xml version="1.0" encoding="utf-8"?>\n<!-- Generated; edit locales/messages.json. -->\n<resources>\n'+''.join(f'    <string name="{ids[k]}" formatted="false">{xml((v[2] if len(v)==3 else k) if index is None else v[index])}</string>\n' for k,v in messages.items())+'</resources>\n',encoding='utf-8')
# DOC L0017: kotlin: Passaggio «kotlin» dello strumento: Generatore del catalogo web e delle risorse Android. Gli argomenti e le operazioni sono descritti nelle righe del corpo.
def kotlin(s):return json.dumps(s,ensure_ascii=False).replace('$','\\$')
# DOC L0018: Esegue il passaggio esplicito «folder=ROOT/'android/app/src/main/java/it/tabatastudio/i18n';folder.mkdir(exist_ok=True)» nel flusso: Generatore del catalogo web e delle risorse Android.
folder=ROOT/'android/app/src/main/java/it/tabatastudio/i18n';folder.mkdir(exist_ok=True)
# DOC L0019: Elabora gli elementi o le iterazioni indicati; gli indici distinguono l’ultimo elemento per le pause o i limiti previsti.
(folder/'MessageIds.kt').write_text('// Generated by scripts/generate-locales.py.\npackage it.tabatastudio.i18n\nimport it.tabatastudio.R\ninternal val messageIds = mapOf(\n'+',\n'.join(f'    {kotlin(k)} to R.string.{v}' for k,v in ids.items())+'\n)\n',encoding='utf-8')
